	allegiance = "Los Dioses Antiguos · adorada por el Martillo Crepuscular",
	aliases = { "Aku'Mai", "Princesa de las Profundidades" },
	sections = {
		{
			title = "Resumen",
			text = [=[Aku'mai es una hidra de tres cabezas y tamaño inmenso, una sierva de los {red:old-gods}Dioses Antiguos{/red}. Cuando la corrupción de aquellos poderes antiguos se filtró en el pozo lunar del templo anegado, ella surgió de sus aguas e hizo de las ruinas su guarida. Lleva una astilla de la fuerza de sus amos, y su hambre de carne viva no tiene fin. El {link:twilight-s-hammer}Martillo Crepuscular{/link} la adora como señal de que los Dioses Antiguos volverán, y la alimenta con sacrificios.]=],
		},
		{
			title = "Importancia",
			text = [=[Aku'mai es la razón por la que el culto llegó a las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}. Para el {link:twilight-s-hammer}Martillo Crepuscular{/link} es divina: la prueba de que sus oscuros patrones aún se agitan bajo el mundo, y una fuente de poder para quien la sirva. Los nagas recogen los zafiros de las cuevas en su nombre, y sus sectarios sueñan con el día en que devuelva a {link:azeroth}Azeroth{/link} el dominio de los Dioses Antiguos. Para el {link:argent-dawn}Alba Argenta{/link} y el {link:earthen-ring}Anillo de la Tierra{/link}, es una herida purulenta en la costa de {link:ashenvale}Vallefresno{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Surgió del pozo lunar corrompido del viejo templo de Elune.
• Ha devorado a los inocentes que el culto le sacrifica.
• Bestias que llevan su nombre, las tortugas mordedoras y los pescadores de Aku'mai, nadan en los estanques, y elementales de agua la sirven.]=],
		},
	},
	chapters = {
		{
			title = "La Princesa de las Profundidades",
			hint = [=[Recupere el viejo manuscrito que yace en las profundidades del templo.]=],
			text = [=[En las profundidades había un escrito más antiguo que el culto, obra de un elfo llamado Lorgalis. Llamaba a Aku'mai la Princesa de las Profundidades, una sierva de los Dioses Antiguos que moraba en el templo y bendecía sus cuevas. Decía que mortales más antiguos la habían traído allí. Solo poseía una astilla del poderío de sus amos, y aun así era inconmensurable. Por eso era adorada, temida y amada.]=],
		},
		{
			title = "Los cristales de las profundidades",
			hint = "Averigüe por qué los nagas recogen zafiros en las cuevas.",
			text = [=[Se vio a los nagas extraer los grandes zafiros de las cuevas, y {link:je-neu-sancrea}Je'neu Sancrea{/link}, del {link:earthen-ring}Anillo de la Tierra{/link}, sintió a los espíritus del agua aferrados a ellos. Una nota arrugada arrebatada a una sacerdotisa {link:naga}naga{/link} contó el resto. Los cristales se llevaban a un cabecilla del culto, para ayudar a sus acuamantes en sus invocaciones. Dominando su poder, el culto esperaba apaciguar a Aku'mai y, algún día, invocarla por completo y devolver el mundo al dominio de los Dioses Antiguos.]=],
		},
	},
	mentions = {
		{ text = "Villanía en {link:blackfathom-deeps}Brazanegra{/link}" },
		{ text = "La esencia de Aku'Mai" },
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Señor Crepuscular Kelris", note = "su sumo sacerdote" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "intentó apaciguarla" },
		{ id = "lady-sarevess", name = "Lady Sarevess", note = "sirve al culto que la adora" },
	},
})

Translate("esMX", "twilight-lord-kelris", {
	title = "Señor Crepuscular Kelris",
	subtitle = "Señor del Martillo Crepuscular en las Cavernas",
	found = [=[El Sagrario del Santuario Lunar, ante el altar de los Dioses Antiguos]=],
	hint = "Busque al amo del culto en el sagrario del templo anegado.",
	allegiance = "Martillo Crepuscular",
	aliases = { "Kelris" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Señor Crepuscular Kelris dirige el {link:twilight-s-hammer}Martillo Crepuscular{/link} en las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}. Permanece en trance en el sagrario del viejo templo, junto al altar donde el culto hace sus ofrendas. Bajo su mando, los sectarios sacrifican inocentes a la hidra {link:aku-mai}Aku'mai{/link}, y a cambio obtienen poder. Kelris maneja la magia de las sombras y del sueño, y en la batalla puede sumir a sus enemigos en un sopor indefenso.]=],
		},
		{
			title = "Importancia",
			text = [=[Durante mucho tiempo, Kelris eludió al {link:argent-dawn}Alba Argenta{/link}. Sus {link:the-night-watch}vigías{/link} de {link:darnassus}Darnassus{/link} dicen que cada vez que el mal se mostraba en estas tierras, Kelris tenía algo que ver, y durante años lo creyeron muerto o perdido. No era ni lo uno ni lo otro. Había descendido a las Cavernas para servir a los {red:old-gods}Dioses Antiguos{/red}, y se proponía devolver el mundo al caos de su era. Los {link:tauren}tauren{/link} de {link:thunder-bluff}Cima del Trueno{/link} lo llaman una criatura de pura maldad.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Condujo al {link:twilight-s-hammer}Martillo Crepuscular{/link} al templo anegado de Elune.
• Alió al culto con los nagas de {link:blackfathom-deeps}Brazanegra{/link}.
• Ofreció inocentes a {link:aku-mai}Aku'mai{/link} a cambio de poder.]=],
		},
	},
	chapters = {
		{
			title = "El informe del explorador",
			hint = [=[Encuentre en las Cavernas al explorador perdido del Alba Argenta.]=],
			text = [=[El {link:argent-dawn}Alba Argenta{/link} envió a un explorador a vigilar el templo, y pasaron semanas sin noticias. Cuando por fin lo encontraron, yacía herido en las cuevas, sin fuerzas. Había descubierto lo que hacía el culto. El {link:twilight-s-hammer}Martillo Crepuscular{/link} y los nagas ocupaban juntos las ruinas, y su líder, Kelris, alimentaba a la hidra con inocentes a cambio de poder. El explorador no podía hacer nada más. Pidió que mataran a Kelris y sacaran su cabeza de las Cavernas.]=],
		},
		{
			title = "La cabeza de Kelris",
			hint = "Ponga fin al reinado del Señor Crepuscular.",
			text = [=[Cuando la cabeza de Kelris llegó al {link:argent-dawn}Alba Argenta{/link} en {link:darnassus}Darnassus{/link}, el vigía del alba Selgorm dijo que por fin todo tenía sentido: el hombre al que creían muerto había estado detrás del mal desde el principio. Por parte de la {link:horde}Horda{/link}, Bashana Runetotem dio gracias a la Madre Tierra, y dijo que sacrificar a otro ante un siervo de los Dioses Antiguos en beneficio propio no tenía palabras. Con su muerte se salvaron muchas vidas inocentes.]=],
		},
	},
	mentions = {
		{ text = "La caída del crepúsculo" },
		{
			text = [=[Villanía en {link:blackfathom-deeps}Brazanegra{/link}, la cabeza llevada a {link:darnassus}Darnassus{/link}]=],
		},
		{
			text = [=[Villanía en {link:blackfathom-deeps}Brazanegra{/link}, la cabeza llevada a {link:thunder-bluff}Cima del Trueno{/link}]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "el poder al que sirve" },
		{ id = "argent-guard-thaelrid", name = "Guardia Argenta Thaelrid", note = "el explorador que lo desenmascaró" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "un siervo del mismo culto" },
	},
})

Translate("esMX", "argent-guard-thaelrid", {
	title = "Guardia Argenta Thaelrid",
	subtitle = "Explorador del Alba Argenta",
	found = [=[Las cuevas cercanas al Estanque de Ask'ar, en las Cavernas de Brazanegra]=],
