	allegiance = "Alba Argenta · Elfos de la noche",
	aliases = { "Thaelrid" },
	sections = {
		{
			title = "Resumen",
			text = [=[El guardia argenta Thaelrid es un {link:night-elves}elfo de la noche{/link} del {link:argent-dawn}Alba Argenta{/link}. La {red:dawnwatcher-shaedlass}vigía del alba Shaedlass{/red} lo envió desde {link:darnassus}Darnassus{/link} a vigilar al {link:twilight-s-hammer}Martillo Crepuscular{/link} y a los nagas en las {link:blackfathom-deeps}Cavernas de Brazanegra{/link}. Descubrió su secreto, pero fue herido y no pudo regresar. Espera en las cuevas, demasiado débil para seguir, y pide a quienes lo encuentran que terminen lo que él no pudo: matar al {link:twilight-lord-kelris}Señor Crepuscular Kelris{/link}.]=],
