			hint = [=[Responda a la llamada del Alba Argenta y busque a su explorador.]=],
			text = [=[Semanas después de entrar en las Cavernas, Thaelrid fue encontrado con vida. Shaedlass había hecho bien en preocuparse, dijo. En aquel lugar corrompido se estaba tramando un plan perverso.]=],
		},
	},
	mentions = {
		{ text = "Villanía en {link:blackfathom-deeps}Brazanegra{/link}" },
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Señor Crepuscular Kelris", note = "el enemigo al que desenmascaró" },
	},
})

Translate("esMX", "morridune", {
