	allegiance = "Antes el Martillo Crepuscular · Darnassus",
	sections = {
		{
			title = "Resumen",
			text = [=[Morridune es un {link:dwarves}enano{/link} de Khaz Modan que una vez siguió al {link:twilight-s-hammer}Martillo Crepuscular{/link}. Llegó a las Cavernas obsesionado con los {red:old-gods}Dioses Antiguos{/red}, con la esperanza de extraer poder de {link:aku-mai}Aku'mai{/link}. Luego vio al culto sacrificar a incontables inocentes, y recobró la cordura. Por ello quedó atrapado en la guarida de la hidra. Cuando Aku'mai murió, gritó que por fin podía marcharse. En agradecimiento, abre un camino hacia {link:darnassus}Darnassus{/link} a quienes mataron a la hidra y son amigos de la {link:alliance}Alianza{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Morridune es la prueba de que algunos de los que caen en el Martillo pueden volver atrás.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "la bestia a la que una vez quiso servir" },
	},
})

Translate("esMX", "ghamoo-ra", {
	title = "Ghamoo-ra",
	subtitle = "La tortuga atormentada",
	found = "La isla del Estanque de Ask'ar",
	hint = [=[Enfréntese a la gran tortuga que vaga por la isla de la cueva inundada.]=],
	allegiance = "Martillo Crepuscular",
	sections = {
		{
			title = "Resumen",
			text = [=[Ghamoo-ra es una tortuga gigante del templo anegado. Se dice que era una de las últimas criaturas pacíficas que vivían allí cuando llegó el {link:twilight-s-hammer}Martillo Crepuscular{/link}. Los sectarios lo despertaron y lo encadenaron. Durante años lo atormentaron en cuerpo y mente, hasta que enloqueció. Le dieron su nombre y lo adiestraron para atacar a cualquier forastero que se acercara a su santuario. Ahora pisotea a todo el que pone pie en su isla, mientras tortugas menores nadan a su alrededor.]=],
		},
		{
			title = "Importancia",
			text = [=[Ghamoo-ra es el primer guardián de las Cavernas, y la crueldad del culto hecha carne.]=],
		},
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Señor Crepuscular Kelris", note = "el amo de sus torturadores" },
	},
})

